/* 학습 해설
 * 소프트웨어 재전달: 같은 목록 노드를 두 번 넣지 않는 이유
 * 나중에 처리할 인터럽트를 목록에 저장할 때 같은 객체를 중복 연결하면 포인터 연결을 망가뜨릴 수 있어 추가 전 상태 확인이 필요합니다.
 * CONFIG_HARDIRQS_SW_RESEND에서는 전역 irq_resend_list와 raw spinlock인 irq_resend_lock을 사용합니다. 각 descriptor 안의 resend_node를 목록에 연결하므로 별도의 요청 객체를 할당하지 않습니다. hlist_unhashed로 아직 연결되지 않았는지 확인한 뒤 hlist_add_head로 앞에 붙입니다. 검사와 추가가 같은 잠금 안에 있어 두 CPU가 동시에 미연결이라고 보고 같은 노드를 두 번 넣는 일을 막습니다. 이미 연결돼 있더라도 tasklet_schedule은 호출되며, 요청 수만큼 목록 항목을 누적하는 구조가 아닙니다.
 * A를 추가하고 B를 추가하면 목록은 B→A가 됩니다. 동일한 A를 다시 요청해도 A 노드가 하나 더 생기지 않는 모습을 그리세요. 장치 이벤트 개수의 정확한 보존과 재처리 필요 여부의 기록은 다릅니다.
 */
static int irq_sw_resend(struct irq_desc *desc)
{
	/*
	 * Validate whether this interrupt can be safely injected from
	 * non interrupt context
	 */
	if (handle_enforce_irqctx(&desc->irq_data))
		return -EINVAL;

	/*
	 * If the interrupt is running in the thread context of the parent
	 * irq we need to be careful, because we cannot trigger it
	 * directly.
	 */
	if (irq_settings_is_nested_thread(desc)) {
		/*
		 * If the parent_irq is valid, we retrigger the parent,
		 * otherwise we do nothing.
		 */
		if (!desc->parent_irq)
			return -EINVAL;

		desc = irq_to_desc(desc->parent_irq);
		if (!desc)
			return -EINVAL;
	}

/* 학습 해설
 * 중첩 인터럽트 재전달: 자식 대신 부모를 깨우는 조건
 * 어떤 장치 인터럽트는 부모의 처리 스레드 안에서 실행돼야 하므로 자식 처리기를 임의의 문맥에서 직접 실행하면 호출 계약을 어기게 됩니다.
 * irq_sw_resend는 먼저 handle_enforce_irqctx로 하드 인터럽트 문맥이 필요한지 검사하고 해당하면 -EINVAL로 거절합니다. 중첩 스레드 방식이면 parent_irq가 0인지 검사하고, 유효한 번호라도 irq_to_desc 조회가 실패하면 -EINVAL입니다. 부모 descriptor를 찾았을 때만 지역 변수 desc를 부모로 바꾸어 부모의 노드를 목록에 넣습니다. 자식 번호를 부모 번호로 영구 변경하는 것이 아니라 이번 재전달 대상 포인터를 바꾸는 것입니다.
 * 자식 C의 parent_irq가 P인 그림을 그리고 목록에 C가 아니라 P의 resend_node가 들어감을 표시하세요. 문맥 강제 검사는 부모로 포인터를 바꾸기 전에 수행된다는 순서도 원문에서 확인하세요.
 */
static int irq_sw_resend(struct irq_desc *desc)
{
	/*
	 * Validate whether this interrupt can be safely injected from
	 * non interrupt context
	 */
	if (handle_enforce_irqctx(&desc->irq_data))
		return -EINVAL;

	/*
	 * If the interrupt is running in the thread context of the parent
	 * irq we need to be careful, because we cannot trigger it
	 * directly.
	 */
	if (irq_settings_is_nested_thread(desc)) {
		/*
		 * If the parent_irq is valid, we retrigger the parent,
		 * otherwise we do nothing.
		 */
		if (!desc->parent_irq)
			return -EINVAL;

		desc = irq_to_desc(desc->parent_irq);
		if (!desc)
			return -EINVAL;
	}

/* 학습 해설
 * 재전달 목록 소비: 처리기를 부를 때 목록 잠금을 놓는 이유
 * 목록에서 항목을 빼는 짧은 작업과 인터럽트 처리기의 긴 실행을 같은 잠금으로 감싸면 다른 요청 추가가 불필요하게 오래 막힙니다.
 * resend_irqs는 raw_spin_lock_irq로 목록 잠금을 잡고 로컬 인터럽트를 끈 뒤 목록이 빌 때까지 반복합니다. 첫 노드를 hlist_entry로 포함 객체인 irq_desc로 바꾸고 hlist_del_init으로 목록에서 제거합니다. raw_spin_unlock으로 목록 잠금만 놓은 상태에서 desc->handle_irq(desc)를 부릅니다. 다시 잠금을 잡고 다음 항목을 꺼내며 마지막에는 raw_spin_unlock_irq로 잠금과 로컬 인터럽트 상태를 처리합니다. 중간의 unlock에는 _irq가 없으므로 처리기를 부르기 전에 여기서 인터럽트를 다시 켜지 않습니다.
 * 목록 잠금 보유, 로컬 인터럽트 비활성, 처리기 실행을 서로 다른 세 줄로 그리세요. 노드를 제거한 뒤 처리기를 호출하는 순서와 목록 잠금 없이 실행하는 구간을 구별하세요.
 */
static void resend_irqs(struct tasklet_struct *unused)
{
	struct irq_desc *desc;

	raw_spin_lock_irq(&irq_resend_lock);
	while (!hlist_empty(&irq_resend_list)) {
		desc = hlist_entry(irq_resend_list.first, struct irq_desc,
				   resend_node);
		hlist_del_init(&desc->resend_node);
		raw_spin_unlock(&irq_resend_lock);
		desc->handle_irq(desc);
		raw_spin_lock(&irq_resend_lock);
	}
	raw_spin_unlock_irq(&irq_resend_lock);
}

/* Tasklet to handle resend: */
static DECLARE_TASKLET(resend_tasklet, resend_irqs);

