static int try_retrigger(struct irq_desc *desc)
{
	if (desc->irq_data.chip->irq_retrigger)
		return desc->irq_data.chip->irq_retrigger(&desc->irq_data);

#ifdef CONFIG_IRQ_DOMAIN_HIERARCHY
	return irq_chip_retrigger_hierarchy(&desc->irq_data);
#else
	return 0;
#endif
}

/* 학습 해설
 * 테스트용 인터럽트 주입: 빠른 성공 경로와 잠금 해제
 * 인터럽트 주입은 장치가 실제로 요청하지 않은 상황을 시험하기 위한 기능이므로 성공 경로와 거절 조건을 순서대로 알아야 합니다.
 * CONFIG_GENERIC_IRQ_INJECTION에서 제공되는 irq_inject_interrupt는 먼저 irq_set_irqchip_state로 PENDING 상태 설정을 요청합니다. 0으로 성공하면 바로 반환하므로 아래 재전달 경로의 NMI·활성화 검사를 거치지 않습니다. 실패하면 irq_get_desc_buslock으로 descriptor와 잠금을 얻으며 없으면 -EINVAL입니다. 이 경로에서는 NMI이거나 활성화되지 않은 IRQ를 거절하고, 나머지는 check_irq_resend(desc,true)로 강제 주입을 시도합니다. descriptor를 얻은 뒤에는 성공·실패 모두 irq_put_desc_busunlock으로 정리합니다.
 * 테스트 전용 API라는 원문 계약을 지키고 학습 중 실제 장치에 무작정 주입하지 마세요. 함수 전체에서 조기 반환 두 곳과 공통 unlock 한 곳을 표시하고 각각 어느 자원을 보유했는지 적으세요.
 */
int irq_inject_interrupt(unsigned int irq)
{
	struct irq_desc *desc;
	unsigned long flags;
	int err;

	/* Try the state injection hardware interface first */
	if (!irq_set_irqchip_state(irq, IRQCHIP_STATE_PENDING, true))
		return 0;

	/* That failed, try via the resend mechanism */
	desc = irq_get_desc_buslock(irq, &flags, 0);
	if (!desc)
		return -EINVAL;

	/*
	 * Only try to inject when the interrupt is:
	 *  - not NMI type
	 *  - activated
	 */
	if (irq_is_nmi(desc) || !irqd_is_activated(&desc->irq_data))
		err = -EINVAL;
	else
		err = check_irq_resend(desc, true);

	irq_put_desc_busunlock(desc, flags);

/* 학습 해설
 * IRQ CPU 이동: 비트 집합의 교집합으로 목적지 확인하기
 * CPU가 꺼지는 동안 인터럽트를 그 CPU로 보내도록 예약한 요청이 남으면 처리할 CPU가 없어질 수 있어 살아 있는 목적지가 있는지 확인합니다.
 * pending_mask는 예약한 목적지 CPU 집합이고 cpu_online_mask는 현재 온라인 CPU 집합입니다. 이동 대기 표시가 없으면 false입니다. 두 집합에 공통 CPU가 없으면 대기 표시를 지우고 false입니다. 공통 CPU가 있으면 force_clear가 참일 때도 표시를 지운 뒤 true를 반환합니다. 따라서 true는 표시가 계속 켜져 있다는 뜻이 아니라 진입 시 대기 중이었고 유효한 온라인 후보가 있었다는 뜻입니다. 이 보조 함수는 CPU를 온라인 집합에서 직접 제거하지 않습니다.
 * pending={2,4}, online={0,4}라면 교집합은 {4}입니다. online={0,1}로 바꾸면 빈 집합입니다. CPU 오프라인 처리 호출 지점의 online mask 상태를 전제로 계산해야 합니다.
 */
bool irq_fixup_move_pending(struct irq_desc *desc, bool force_clear)
{
	struct irq_data *data = irq_desc_get_irq_data(desc);

	if (!irqd_is_setaffinity_pending(data))
		return false;

	/*
	 * The outgoing CPU might be the last online target in a pending
	 * interrupt move. If that's the case clear the pending move bit.
	 */
	if (!cpumask_intersects(desc->pending_mask, cpu_online_mask)) {
		irqd_clr_move_pending(data);
		return false;
	}
	if (force_clear)
		irqd_clr_move_pending(data);
	return true;
}

void irq_move_masked_irq(struct irq_data *idata)
{
	struct irq_desc *desc = irq_data_to_desc(idata);
	struct irq_data *data = &desc->irq_data;
	struct irq_chip *chip = data->chip;

/* 학습 해설
 * IRQ 이동 전 검사: 대기 표시와 목적지 집합은 별개다
 * 이동 상태를 나타내는 한 비트와 이동할 CPU 목록은 서로 다른 데이터이므로 어떤 조기 반환에서 무엇이 지워지는지 구분해야 합니다.
 * irq_move_masked_irq는 최상위 descriptor의 irq_data와 chip을 사용합니다. 이동 대기가 없으면 즉시 반환하고, 있으면 먼저 대기 표시를 지웁니다. CPU 전용 IRQ이면 WARN_ON 뒤 반환하고, pending_mask가 비었거나 irq_set_affinity 콜백이 없어도 반환합니다. 이 조기 반환들은 함수 끝의 cpumask_clear에 도달하지 않습니다. 이후 assert_raw_spin_locked는 descriptor 잠금 보유를 검사하는 표현이며 잠금을 대신 획득하지 않습니다.
 * pending 표시와 pending_mask를 두 칸으로 나누고 각 조기 반환에서 값을 추적하세요. 함수 이름에 masked가 있으므로 호출자가 IRQ를 가린 상태로 진입해야 한다는 원문 전제도 함께 적으세요.
 */
void irq_move_masked_irq(struct irq_data *idata)
{
	struct irq_desc *desc = irq_data_to_desc(idata);
	struct irq_data *data = &desc->irq_data;
	struct irq_chip *chip = data->chip;

	if (likely(!irqd_is_setaffinity_pending(data)))
		return;

	irqd_clr_move_pending(data);

	/*
	 * Paranoia: cpu-local interrupts shouldn't be calling in here anyway.
	 */
	if (irqd_is_per_cpu(data)) {
		WARN_ON(1);
		return;
	}

	if (unlikely(cpumask_empty(desc->pending_mask)))
		return;

	if (!chip->irq_set_affinity)
		return;

	assert_raw_spin_locked(&desc->lock);

/* 학습 해설
 * IRQ 이동 재시도: EBUSY일 때 목적지를 남기는 이유
 * 이동 요청이 잘못된 것이 아니라 이전 벡터 정리가 아직 끝나지 않은 경우에는 다음 기회에 같은 목적지로 재시도할 수 있어야 합니다.
 * 온라인 CPU와 pending_mask가 겹치면 irq_do_set_affinity(data,pending_mask,false)를 호출합니다. 반환값이 -EBUSY이면 이동 대기 표시를 다시 켜고 바로 반환해 pending_mask를 보존합니다. 아래 벡터 관리의 정리가 완료되지 않아 다음 인터럽트에서 재시도해야 할 수 있기 때문입니다. 다른 결과이거나 온라인 목적지가 없으면 마지막 cpumask_clear에 도달합니다. 이 함수의 반환 타입은 void이므로 일반 오류 코드를 호출자에게 그대로 전달하지 않습니다.
 * 첫 호출이 -EBUSY, 다음 호출이 0인 두 시점을 그리세요. 첫 호출 뒤 목적지 집합과 대기 표시가 남고 두 번째 성공 뒤에는 정리되는 모습을 확인하세요.
 */
void irq_move_masked_irq(struct irq_data *idata)
{
	struct irq_desc *desc = irq_data_to_desc(idata);
	struct irq_data *data = &desc->irq_data;
	struct irq_chip *chip = data->chip;

	if (likely(!irqd_is_setaffinity_pending(data)))
		return;

	irqd_clr_move_pending(data);

	/*
	 * Paranoia: cpu-local interrupts shouldn't be calling in here anyway.
	 */
	if (irqd_is_per_cpu(data)) {
		WARN_ON(1);
		return;
	}

	if (unlikely(cpumask_empty(desc->pending_mask)))
		return;

	if (!chip->irq_set_affinity)
		return;

	assert_raw_spin_locked(&desc->lock);

/* 학습 해설
 * IRQ 마스킹 복원: 원래 가려져 있던 요청을 임의로 열지 않기
 * 임시로 설정을 바꾼 함수가 끝날 때에는 자신이 바꾼 상태만 되돌려야 다른 처리 코드가 유지하던 보호를 깨뜨리지 않습니다.
 * __irq_move_irq는 계층형 IRQ일 때도 descriptor의 최상위 irq_data를 가져옵니다. IRQ가 disabled 상태면 바로 반환합니다. 아니라면 masked 상태를 지역 bool에 저장하고, 원래 가려져 있지 않았을 때만 chip->irq_mask를 호출합니다. irq_move_masked_irq 뒤에도 원래 가려져 있지 않았을 때만 irq_unmask합니다. 이미 ONESHOT 스레드 처리 때문에 가려져 있던 IRQ를 무조건 열면 스레드가 끝나기 전에 같은 요청이 반복돼 인터럽트 폭주를 일으킬 수 있습니다.
 * 원래 masked=false와 true 두 경우에 mask, move, unmask 호출 횟수를 써 보세요. 각각 1·1·1과 0·1·0입니다. disabled=true인 경우에는 세 동작 모두 하지 않습니다.
 */
void __irq_move_irq(struct irq_data *idata)
{
	bool masked;

	/*
	 * Get top level irq_data when CONFIG_IRQ_DOMAIN_HIERARCHY is enabled,
	 * and it should be optimized away when CONFIG_IRQ_DOMAIN_HIERARCHY is
	 * disabled. So we avoid an "#ifdef CONFIG_IRQ_DOMAIN_HIERARCHY" here.
	 */
	idata = irq_desc_get_irq_data(irq_data_to_desc(idata));

	if (unlikely(irqd_irq_disabled(idata)))
		return;

	/*
	 * Be careful vs. already masked interrupts. If this is a
	 * threaded interrupt with ONESHOT set, we can end up with an
	 * interrupt storm.
	 */
	masked = irqd_irq_masked(idata);
	if (!masked)
		idata->chip->irq_mask(idata);
	irq_move_masked_irq(idata);
	if (!masked)
		idata->chip->irq_unmask(idata);
}

/* 학습 해설
 * 레거시 IRQ 탐색: 먼저 묵은 신호를 흘려보내는 이유
 * 어느 IRQ 선에 장치가 연결됐는지 관찰로 찾으려면 시험 전에 남아 있던 신호를 새로 발생시킨 신호로 착각하지 않아야 합니다.
 * probe_irq_on은 async_synchronize_full로 기존 비동기 초기화 작업을 기다리고 probing_active mutex를 잡습니다. handler가 없고 probe 가능한 IRQ만 역순으로 순회하며 필요한 chip에는 IRQ_TYPE_PROBE를 알리고 IRQ_NORESEND로 활성화합니다. 20ms를 기다려 오래된 신호가 나오게 한 다음 다시 순회하여 AUTODETECT와 WAITING을 세우고 재시작합니다. 두 번째 startup의 반환값이 0이 아니면 PENDING도 세웁니다. 이 단계의 반환값을 이 함수가 직접 사용자 오류로 반환하는 구조는 아닙니다.
 * 기존 비동기 작업 기다림→전역 mutex→첫 startup→20ms→표시 설정과 두 번째 startup 순서를 그리세요. msleep을 쓰므로 잠들 수 없는 문맥에서 임의 호출하면 안 됩니다.
 */
unsigned long probe_irq_on(void)
{
	struct irq_desc *desc;
	unsigned long mask = 0;
	int i;

	/*
	 * quiesce the kernel, or at least the asynchronous portion
	 */
	async_synchronize_full();
	mutex_lock(&probing_active);
	/*
	 * something may have generated an irq long ago and we want to
	 * flush such a longstanding irq before considering it as spurious.
	 */
	for_each_irq_desc_reverse(i, desc) {
		raw_spin_lock_irq(&desc->lock);
		if (!desc->action && irq_settings_can_probe(desc)) {
			/*
			 * Some chips need to know about probing in
			 * progress:
			 */
			if (desc->irq_data.chip->irq_set_type)
				desc->irq_data.chip->irq_set_type(&desc->irq_data,
							 IRQ_TYPE_PROBE);
			irq_activate_and_startup(desc, IRQ_NORESEND);

/* 학습 해설
 * IRQ 탐색 후보: WAITING 비트로 조용했던 선 고르기
 * 시험 신호를 보내기 전부터 혼자 발생한 IRQ는 해당 장치의 새 시험 결과인지 구별하기 어려우므로 후보에서 제거합니다.
 * 두 번째 startup 이후 100ms를 기다리고 순방향으로 전체 descriptor를 검사합니다. AUTODETECT가 있는데 WAITING이 꺼졌으면 이미 신호가 발생한 것으로 보고 AUTODETECT를 지우고 shutdown 및 deactivate합니다. 계속 WAITING인 IRQ 중 번호가 32보다 작을 때만 결과 mask에 1 << i를 OR합니다. 번호가 큰 IRQ는 반환 mask에 담기지 않아도 내부 탐색 상태가 남을 수 있으므로 종료 함수는 전체 IRQ를 정리해야 합니다. probe_irq_on은 probing_active mutex를 보유한 채 반환합니다.
 * IRQ 3과 5만 조용히 기다렸다면 mask는 8 | 32 = 40입니다. 이 값은 IRQ 번호 40이 아니라 두 후보를 담은 비트 집합입니다. 장치 시험 후 probe_irq_mask 또는 probe_irq_off 중 하나로 반드시 종료하는 사용 흐름을 적으세요.
 */
unsigned long probe_irq_on(void)
{
	struct irq_desc *desc;
	unsigned long mask = 0;
	int i;

	/*
	 * quiesce the kernel, or at least the asynchronous portion
	 */
	async_synchronize_full();
	mutex_lock(&probing_active);
	/*
	 * something may have generated an irq long ago and we want to
	 * flush such a longstanding irq before considering it as spurious.
	 */
	for_each_irq_desc_reverse(i, desc) {
		raw_spin_lock_irq(&desc->lock);
		if (!desc->action && irq_settings_can_probe(desc)) {
			/*
			 * Some chips need to know about probing in
			 * progress:
			 */
			if (desc->irq_data.chip->irq_set_type)
				desc->irq_data.chip->irq_set_type(&desc->irq_data,
							 IRQ_TYPE_PROBE);
			irq_activate_and_startup(desc, IRQ_NORESEND);

/* 학습 해설
 * IRQ 탐색 비트 결과: 반환 대상 밖의 IRQ도 정리해야 하는 이유
 * 결과로 돌려줄 범위가 좁더라도 시작 단계에서 더 넓은 범위를 변경했다면 정리는 변경한 모든 객체에 수행해야 합니다.
 * probe_irq_mask는 전체 IRQ를 순회하면서 descriptor 잠금을 잡습니다. AUTODETECT 중 번호가 16보다 작고 WAITING이 꺼진 항목의 비트를 결과에 넣습니다. 반환 대상 여부와 상관없이 모든 AUTODETECT 항목의 표시를 지우고 shutdown 및 deactivate합니다. 끝에서 probing_active mutex를 풀고 mask & val을 반환합니다. 시작 함수가 32 미만 후보를 표현하는 것과 이 함수가 16 미만 발생 결과를 표현하는 것은 서로 다른 제한입니다.
 * 관찰 결과가 {3,7}이고 입력 val이 {3,5}이면 교집합 {3}, 즉 8만 반환합니다. IRQ 20이 AUTODETECT라면 반환 비트에는 없어도 정리 대상임을 표시하세요.
 */
unsigned int probe_irq_mask(unsigned long val)
{
	unsigned int mask = 0;
	struct irq_desc *desc;
	int i;

	for_each_irq_desc(i, desc) {
		raw_spin_lock_irq(&desc->lock);
		if (desc->istate & IRQS_AUTODETECT) {
			if (i < 16 && !(desc->istate & IRQS_WAITING))
				mask |= 1 << i;

			desc->istate &= ~IRQS_AUTODETECT;
			irq_shutdown_and_deactivate(desc);
		}
		raw_spin_unlock_irq(&desc->lock);
	}
	mutex_unlock(&probing_active);

	return mask & val;
}
EXPORT_SYMBOL(probe_irq_mask);

/**
 *	probe_irq_off	- end an interrupt autodetect
 *	@val: mask of potential interrupts (unused)
 *
 *	Scans the unused interrupt lines and returns the line which
 *	appears to have triggered the interrupt. If no interrupt was
 *	found then zero is returned. If more than one interrupt is
 *	found then minus the first candidate is returned to indicate
 *	their is doubt.
 *
 *	The interrupt probe logic state is returned to its previous
 *	value.
 *
 *	BUGS: When used in a module (which arguably shouldn't happen)
 *	nothing prevents two IRQ probe callers from overlapping. The
 *	results of this are non-optimal.
 */

/* 학습 해설
 * IRQ 탐색 단일 결과: 모호함을 음수로 알리는 규칙
 * 관찰 중 여러 IRQ가 발생하면 어느 선이 시험 장치의 것인지 확정할 수 없으므로 첫 후보 하나만 성공처럼 돌려주면 안 됩니다.
 * probe_irq_off는 전체 AUTODETECT 항목에서 WAITING이 꺼진 수를 세고 첫 번호를 irq_found에 보관합니다. 각 항목은 표시를 지우고 shutdown 및 deactivate하며 끝에서 mutex를 풉니다. 관찰이 없으면 초기값 0, 하나면 그 번호, 여러 개면 첫 번호의 음수를 반환합니다. val 인자는 실제 본문에서 사용하지 않으므로 probe_irq_mask처럼 입력 집합으로 결과를 거르지 않습니다. 반환 0과 -첫 번호 표현은 첫 후보가 IRQ 0인 경계에서 구분력이 없으므로 결과 부호만으로 모든 가능한 번호를 완벽히 표현하는 API는 아닙니다.
 * 관찰 {5}면 5, 관찰 {5,7}이면 -5, 관찰 없음이면 0을 직접 계산하세요. 이 함수와 probe_irq_mask를 둘 다 연속 호출하는 것이 아니라 시작에 대응하는 종료 방식 하나를 선택합니다.
 */
int probe_irq_off(unsigned long val)
{
	int i, irq_found = 0, nr_of_irqs = 0;
	struct irq_desc *desc;

	for_each_irq_desc(i, desc) {
		raw_spin_lock_irq(&desc->lock);

		if (desc->istate & IRQS_AUTODETECT) {
			if (!(desc->istate & IRQS_WAITING)) {
				if (!nr_of_irqs)
					irq_found = i;
				nr_of_irqs++;
			}
			desc->istate &= ~IRQS_AUTODETECT;
			irq_shutdown_and_deactivate(desc);
		}
		raw_spin_unlock_irq(&desc->lock);
	}
	mutex_unlock(&probing_active);

	if (nr_of_irqs > 1)
		irq_found = -irq_found;

	return irq_found;
}

