/* 학습 해설
 * CPU 종료 시 IRQ 이동: chip 검사와 이전 이동 정리를 먼저 한다
 * IRQ 객체가 남아 있어도 하드웨어를 조작하는 chip이 이미 정리됐거나 이동 기능이 없을 수 있어 객체 존재만으로 이동 함수를 호출하면 안 됩니다.
 * migrate_one_irq는 descriptor에서 irq_data와 chip을 얻습니다. chip이 없거나 irq_set_affinity 콜백이 없으면 디버그 메시지를 남기고 false입니다. 지원되면 irq_force_complete_move로 이전 이동의 남은 벡터 정리를 먼저 요청합니다. 이후 per-CPU IRQ, 시작되지 않은 IRQ, 보정 불필요 IRQ는 실제 이동을 생략하지만 irq_fixup_move_pending(desc,false)는 실행해 종료 CPU만 남은 대기 요청을 정리합니다. desc->action 유무는 생략 조건이 아닙니다. chained IRQ도 이동해야 하기 때문입니다.
 * chip 없음→이전 이동 정리도 생략, per-CPU→이전 이동 정리 뒤 대기 요청 보정, 일반 IRQ→다음 단계로 진행이라는 세 경로를 그리세요. 원문의 radix tree라는 오래된 주석을 현재 저장소 구현의 증거로 삼지 마세요.
 */
static bool migrate_one_irq(struct irq_desc *desc)
{
	struct irq_data *d = irq_desc_get_irq_data(desc);
	struct irq_chip *chip = irq_data_get_irq_chip(d);
	bool maskchip = !irq_can_move_pcntxt(d) && !irqd_irq_masked(d);
	const struct cpumask *affinity;
	bool brokeaff = false;
	int err;

	/*
	 * IRQ chip might be already torn down, but the irq descriptor is
	 * still in the radix tree. Also if the chip has no affinity setter,
	 * nothing can be done here.
	 */
	if (!chip || !chip->irq_set_affinity) {
		pr_debug("IRQ %u: Unable to migrate away\n", d->irq);
		return false;
	}

	/*
	 * Complete an eventually pending irq move cleanup. If this
	 * interrupt was moved in hard irq context, then the vectors need
	 * to be cleaned up. It can't wait until this interrupt actually
	 * happens and this CPU was involved.
	 */
	irq_force_complete_move(desc);

/* 학습 해설
 * CPU 종료와 예약 affinity: 마지막 요청을 잃지 않고 이어받기
 * 사용자가 목적지 변경을 요청했지만 아직 적용되지 않은 순간에 CPU가 꺼질 수 있습니다. 이전 목적지만 읽으면 가장 최근 요청을 잃을 수 있습니다.
 * irq_fixup_move_pending(desc,true)가 true이면 pending_mask를 이동 목적지로 재사용합니다. 대기 요청이 없거나 그 집합에 온라인 CPU가 없으면 현재 일반 affinity를 사용합니다. force_clear=true는 대기 표시를 지우지만 유효한 목적지 집합 자체를 즉시 지우지는 않기 때문에 그 포인터를 재사용할 수 있습니다. 이동 전에 계산한 maskchip은 프로세스 문맥 이동이 불가능하고 아직 masked가 아닐 때 참입니다. 이 조건과 irq_mask 콜백 존재 조건을 모두 만족할 때 chip을 가립니다.
 * 기존 affinity={1}, pending={2}, online={0,2}, 종료 CPU=1이면 새 요청 {2}가 선택되는 과정을 적으세요. pending={1}이면 온라인 교집합이 없어 일반 affinity로 돌아가는 분기도 비교하세요.
 */
static bool migrate_one_irq(struct irq_desc *desc)
{
	struct irq_data *d = irq_desc_get_irq_data(desc);
	struct irq_chip *chip = irq_data_get_irq_chip(d);
	bool maskchip = !irq_can_move_pcntxt(d) && !irqd_irq_masked(d);
	const struct cpumask *affinity;
	bool brokeaff = false;
	int err;

	/*
	 * IRQ chip might be already torn down, but the irq descriptor is
	 * still in the radix tree. Also if the chip has no affinity setter,
	 * nothing can be done here.
	 */
	if (!chip || !chip->irq_set_affinity) {
		pr_debug("IRQ %u: Unable to migrate away\n", d->irq);
		return false;
	}

	/*
	 * Complete an eventually pending irq move cleanup. If this
	 * interrupt was moved in hard irq context, then the vectors need
	 * to be cleaned up. It can't wait until this interrupt actually
	 * happens and this CPU was involved.
	 */
	irq_force_complete_move(desc);

/* 학습 해설
 * 관리형 IRQ와 일반 IRQ: 갈 곳이 없으면 중단하거나 범위를 넓힌다
 * 목적지 집합에 온라인 CPU가 하나도 없을 때는 서비스 지속과 배치 제약 중 무엇을 지켜야 하는지가 IRQ 종류에 따라 달라집니다.
 * 선택한 affinity와 온라인 집합이 겹치지 않으면 managed IRQ는 managed_shutdown 표시를 세우고 irq_shutdown_and_deactivate로 중단한 뒤 false를 반환합니다. 이 경우 affinity 자체를 바꾸지 않아 나중에 대상 CPU가 돌아오면 원래 배치 조건을 복원할 수 있습니다. 일반 IRQ는 대신 cpu_online_mask 전체를 목적지로 선택하고 brokeaff=true로 요청 범위를 벗어났음을 기록합니다. 이후 설정이 성공해야 이 true가 최종 결과로 유지됩니다.
 * 목적지 {2}, 온라인 {0,1}을 두 종류에 각각 대입하세요. managed는 중단하고 {2}를 유지하며, 일반 IRQ는 {0,1}에서 처리할 수 있도록 시도합니다. 중단 분기는 마지막 unmask에 도달하지 않습니다.
 */
static bool migrate_one_irq(struct irq_desc *desc)
{
	struct irq_data *d = irq_desc_get_irq_data(desc);
	struct irq_chip *chip = irq_data_get_irq_chip(d);
	bool maskchip = !irq_can_move_pcntxt(d) && !irqd_irq_masked(d);
	const struct cpumask *affinity;
	bool brokeaff = false;
	int err;

	/*
	 * IRQ chip might be already torn down, but the irq descriptor is
	 * still in the radix tree. Also if the chip has no affinity setter,
	 * nothing can be done here.
	 */
	if (!chip || !chip->irq_set_affinity) {
		pr_debug("IRQ %u: Unable to migrate away\n", d->irq);
		return false;
	}

	/*
	 * Complete an eventually pending irq move cleanup. If this
	 * interrupt was moved in hard irq context, then the vectors need
	 * to be cleaned up. It can't wait until this interrupt actually
	 * happens and this CPU was involved.
	 */
	irq_force_complete_move(desc);

/* 학습 해설
 * IRQ 이동 force 인자: CPU를 끄는데 강제를 켜면 안 되는 이유
 * 함수 인자 이름 force만 보고 더 확실하게 이동시키는 옵션이라고 생각하면 오히려 꺼지는 CPU를 목적지로 남길 수 있습니다.
 * 이 파일은 irq_do_set_affinity의 force 인자로 false를 전달합니다. 이 인자는 온라인 CPU 필터를 무시하고 입력 집합을 그대로 chip에 전달할지와 연결됩니다. force를 켜면 꺼지는 CPU가 입력 집합에 남아 있어도 다시 목적지로 설정될 수 있으므로 CPU 종료 이주에서는 사용하지 않습니다. manage.c 구현은 force가 거짓일 때 온라인 집합과 교집합을 계산해 chip에 전달하고 유효한 교집합이 없으면 -EINVAL로 처리합니다.
 * 입력 {1,2}, 온라인 {2}에서 false 경로는 chip에 {2}를 전달하는 과정을 따라가세요. 여기서 일반 affinity에 저장되는 요청 집합과 chip에 전달할 집합을 다시 구별하세요.
 */
static bool migrate_one_irq(struct irq_desc *desc)
{
	struct irq_data *d = irq_desc_get_irq_data(desc);
	struct irq_chip *chip = irq_data_get_irq_chip(d);
	bool maskchip = !irq_can_move_pcntxt(d) && !irqd_irq_masked(d);
	const struct cpumask *affinity;
	bool brokeaff = false;
	int err;

	/*
	 * IRQ chip might be already torn down, but the irq descriptor is
	 * still in the radix tree. Also if the chip has no affinity setter,
	 * nothing can be done here.
	 */
	if (!chip || !chip->irq_set_affinity) {
		pr_debug("IRQ %u: Unable to migrate away\n", d->irq);
		return false;
	}

	/*
	 * Complete an eventually pending irq move cleanup. If this
	 * interrupt was moved in hard irq context, then the vectors need
	 * to be cleaned up. It can't wait until this interrupt actually
	 * happens and this CPU was involved.
	 */
	irq_force_complete_move(desc);

/* 학습 해설
 * IRQ 벡터 부족: 온라인 CPU가 있어도 이동이 실패하는 이유
 * CPU가 켜져 있어도 그 CPU에서 인터럽트를 구분하는 벡터 자리가 부족할 수 있습니다. 목적지의 존재와 하드웨어 자원 여유는 서로 다른 조건입니다.
 * irq_do_set_affinity가 -ENOSPC를 반환하고 managed IRQ가 아니며 affinity 포인터가 cpu_online_mask와 다를 때만 온라인 전체 집합으로 범위를 넓혀 한 번 더 시도합니다. brokeaff도 true로 바꿉니다. 이미 온라인 전체를 넘겼다면 같은 대상으로 또 시도하지 않습니다. 여기의 affinity != cpu_online_mask는 집합 내용 비교가 아니라 포인터 비교입니다. 별도 mask 객체가 같은 비트들을 가지고 있어도 포인터가 다르면 이 재시도 조건을 통과할 수 있습니다.
 * 요청 집합 {1}, 온라인 {0,1}에서 CPU 1의 벡터가 부족하면 두 번째 시도는 {0,1}을 사용합니다. -EINVAL, managed=true, 이미 cpu_online_mask를 선택한 경우에는 같은 재시도가 없는 것을 비교하세요.
 */
static bool migrate_one_irq(struct irq_desc *desc)
{
	struct irq_data *d = irq_desc_get_irq_data(desc);
	struct irq_chip *chip = irq_data_get_irq_chip(d);
	bool maskchip = !irq_can_move_pcntxt(d) && !irqd_irq_masked(d);
	const struct cpumask *affinity;
	bool brokeaff = false;
	int err;

	/*
	 * IRQ chip might be already torn down, but the irq descriptor is
	 * still in the radix tree. Also if the chip has no affinity setter,
	 * nothing can be done here.
	 */
	if (!chip || !chip->irq_set_affinity) {
		pr_debug("IRQ %u: Unable to migrate away\n", d->irq);
		return false;
	}

	/*
	 * Complete an eventually pending irq move cleanup. If this
	 * interrupt was moved in hard irq context, then the vectors need
	 * to be cleaned up. It can't wait until this interrupt actually
	 * happens and this CPU was involved.
	 */
	irq_force_complete_move(desc);

/* 학습 해설
 * IRQ 이주의 반환값: false가 반드시 실패를 뜻하지 않는다
 * bool 반환값을 성공·실패로 단정하면 정상 이동, 이동 불필요, 관리형 중단을 잘못 해석할 수 있어 반환 변수가 나타내는 사실을 읽어야 합니다.
 * migrate_one_irq의 최종 반환은 brokeaff입니다. 기존 affinity 밖으로 범위를 넓혀 설정에 성공한 경우에 true가 남습니다. 기존 범위 안의 정상 이동은 false일 수 있습니다. 설정이 최종 실패하면 속도 제한 경고를 남기고 brokeaff=false로 되돌립니다. 일반 설정 경로 끝에서는 maskchip이 참이고 irq_unmask가 존재할 때 다시 엽니다. 이 함수는 일반적인 이전 affinity 복원이나 오류값 전달을 구현하지 않으며 false만으로 모든 결과를 구분할 수 없습니다.
 * 기존 범위 안 성공→false, 범위 확대 성공→true, 범위 확대 후 실패→false의 세 사례를 만드세요. 호출자가 이 결과로 실패 복구가 아니라 affinity 이탈에 대한 디버그 메시지를 결정함을 확인하세요.
 */
static bool migrate_one_irq(struct irq_desc *desc)
{
	struct irq_data *d = irq_desc_get_irq_data(desc);
	struct irq_chip *chip = irq_data_get_irq_chip(d);
	bool maskchip = !irq_can_move_pcntxt(d) && !irqd_irq_masked(d);
	const struct cpumask *affinity;
	bool brokeaff = false;
	int err;

	/*
	 * IRQ chip might be already torn down, but the irq descriptor is
	 * still in the radix tree. Also if the chip has no affinity setter,
	 * nothing can be done here.
	 */
	if (!chip || !chip->irq_set_affinity) {
		pr_debug("IRQ %u: Unable to migrate away\n", d->irq);
		return false;
	}

	/*
	 * Complete an eventually pending irq move cleanup. If this
	 * interrupt was moved in hard irq context, then the vectors need
	 * to be cleaned up. It can't wait until this interrupt actually
	 * happens and this CPU was involved.
	 */
	irq_force_complete_move(desc);

/* 학습 해설
 * CPU 오프라인 IRQ 순회: handler 없는 chained IRQ도 이동한다
 * 인터럽트 컨트롤러가 다른 컨트롤러로 연결되는 구조에서는 일반 action 목록이 없는 IRQ도 전달 경로의 일부이므로 빠뜨리면 안 됩니다.
 * irq_migrate_all_off_this_cpu는 현재 CPU가 이미 오프라인 표시된 시점에 모든 active IRQ를 순회합니다. 번호를 descriptor로 바꾸고 각 desc->lock을 raw_spin_lock으로 잡은 동안 migrate_one_irq를 실행합니다. 잠금을 푼 뒤 affinity_broken이 true인 경우에만 속도 제한 디버그 메시지를 남깁니다. 이 함수 자체는 irq_lock_sparse나 로컬 IRQ save를 하지 않으므로 CPU hotplug 호출 경로의 직렬화와 실행 문맥을 전제로 읽어야 합니다. desc->action 필터를 추가하면 chained IRQ가 빠질 수 있습니다.
 * active IRQ 10은 일반 handler, 11은 chained 경로라고 가정하고 둘 다 순회 대상에 남겨 두세요. 함수 안에서 직접 얻는 잠금과 호출자가 제공해야 하는 실행 조건을 별도 칸에 적으세요.
 */
void irq_migrate_all_off_this_cpu(void)
{
	struct irq_desc *desc;
	unsigned int irq;

	for_each_active_irq(irq) {
		bool affinity_broken;

		desc = irq_to_desc(irq);
		raw_spin_lock(&desc->lock);
		affinity_broken = migrate_one_irq(desc);
		raw_spin_unlock(&desc->lock);

		if (affinity_broken) {
			pr_debug_ratelimited("IRQ %u: no longer affine to CPU%u\n",
					    irq, smp_processor_id());
		}
	}
}

static bool hk_should_isolate(struct irq_data *data, unsigned int cpu)
{
	const struct cpumask *hk_mask;

	if (!housekeeping_enabled(HK_TYPE_MANAGED_IRQ))
		return false;

/* 학습 해설
 * Housekeeping CPU: 부분집합 검사로 IRQ 격리 복원하기
 * 일부 CPU에서 잡다한 커널 작업을 줄이려면 인터럽트를 처리할 CPU와 작업 격리에 사용할 CPU의 역할을 구분해야 합니다.
 * hk_should_isolate는 HK_TYPE_MANAGED_IRQ housekeeping 정책이 꺼져 있으면 false입니다. 정책이 켜졌더라도 현재 effective affinity가 housekeeping 집합의 부분집합이면 이미 원하는 쪽에만 배치돼 있으므로 false입니다. 그렇지 않을 때 새로 온라인이 되는 cpu가 housekeeping 집합에 속하는지를 반환합니다. 즉 다른 곳에서 처리하던 IRQ를 돌아온 housekeeping CPU 쪽으로 옮길 필요를 판단합니다. 부분집합과 교집합은 다른 검사이며 effective 집합이 빈 경우 부분집합 검사는 참입니다.
 * housekeeping={0,1}, effective={2}, 복귀 CPU=1이면 true입니다. effective={0}이면 이미 적절해 false이고, 복귀 CPU=2이면 housekeeping CPU가 아니어서 false입니다. effective={0,2}도 부분집합은 아니라는 점을 계산하세요.
 */
static bool hk_should_isolate(struct irq_data *data, unsigned int cpu)
{
	const struct cpumask *hk_mask;

	if (!housekeeping_enabled(HK_TYPE_MANAGED_IRQ))
		return false;

	hk_mask = housekeeping_cpumask(HK_TYPE_MANAGED_IRQ);
	if (cpumask_subset(irq_data_get_effective_affinity_mask(data), hk_mask))
		return false;

	return cpumask_test_cpu(cpu, hk_mask);
}

static void irq_restore_affinity_of_irq(struct irq_desc *desc, unsigned int cpu)
{
	struct irq_data *data = irq_desc_get_irq_data(desc);
	const struct cpumask *affinity = irq_data_get_affinity_mask(data);

	if (!irqd_affinity_is_managed(data) || !desc->action ||
	    !irq_data_get_irq_chip(data) || !cpumask_test_cpu(cpu, affinity))
		return;

	/*
	 * Don't restore suspended interrupts here when a system comes back
	 * from S3. They are reenabled via resume_device_irqs().
	 */

/* 학습 해설
 * CPU 복귀 시 IRQ 복원: 관리형·사용 중·정상 chip·목적지 조건
 * CPU가 다시 켜졌다는 이유로 모든 IRQ를 재시작하면 사용하지 않는 IRQ나 시스템 절전 때문에 중단한 장치까지 잘못 활성화할 수 있습니다.
 * irq_restore_affinity_of_irq는 managed IRQ인지, action이 있는지, chip이 있는지, 복귀 CPU가 일반 affinity에 속하는지 모두 확인합니다. 하나라도 맞지 않으면 반환합니다. 이어 IRQS_SUSPENDED면 반환하여 S3 절전 복귀의 인터럽트 재활성화를 resume_device_irqs 경로에 맡깁니다. 오프라인 순회에서 action 필터를 쓰지 않는 것과 달리 이 관리형 복원 함수에는 명시적인 action 검사가 있습니다. 서로 다른 역할의 함수를 같은 규칙으로 일반화하면 안 됩니다.
 * managed=true, action 존재, chip 존재, affinity={1,2}에서 복귀 CPU=2인 사례를 시작점으로 삼고 각 조건을 하나씩 거짓으로 바꿔 반환 위치를 찾으세요. SUSPENDED와 managed_shutdown은 서로 다른 상태입니다.
 */
static void irq_restore_affinity_of_irq(struct irq_desc *desc, unsigned int cpu)
{
	struct irq_data *data = irq_desc_get_irq_data(desc);
	const struct cpumask *affinity = irq_data_get_affinity_mask(data);

	if (!irqd_affinity_is_managed(data) || !desc->action ||
	    !irq_data_get_irq_chip(data) || !cpumask_test_cpu(cpu, affinity))
		return;

	/*
	 * Don't restore suspended interrupts here when a system comes back
	 * from S3. They are reenabled via resume_device_irqs().
	 */
	if (desc->istate & IRQS_SUSPENDED)
		return;

	if (irqd_is_managed_and_shutdown(data))
		irq_startup(desc, IRQ_RESEND, IRQ_START_COND);

	/*
	 * If the interrupt can only be directed to a single target
	 * CPU then it is already assigned to a CPU in the affinity
	 * mask. No point in trying to move it around unless the
	 * isolation mechanism requests to move it to an upcoming
	 * housekeeping CPU.
	 */

/* 학습 해설
 * 관리형 IRQ 재시작과 단일 목적지: 불필요한 이동 줄이기
 * 복귀 CPU를 이용할 수 있게 됐더라도 이미 적절한 CPU에서 동작하는 단일 목적지 IRQ를 매번 옮기면 필요 없는 설정 변경이 생깁니다.
 * 진입 조건을 통과한 IRQ가 managed shutdown 상태이면 irq_startup(desc,IRQ_RESEND,IRQ_START_COND)를 호출합니다. 그 뒤 single_target이 아니거나 hk_should_isolate가 true일 때만 irq_set_affinity_locked(data,affinity,false)를 호출합니다. 단일 목적지 IRQ는 이미 허용 집합의 한 CPU에 배치됐다면 그대로 두되, housekeeping 복원이 필요하면 이동을 허용합니다. 이 함수는 void이며 startup과 affinity 설정의 반환값을 검사해 호출자에게 전달하는 코드가 없습니다. 복원 호출 자체를 성공 보장으로 설명하면 안 됩니다.
 * single_target=true·isolate=false면 설정 생략, true·true면 설정 실행, false면 설정 실행의 세 사례를 만드세요. C의 ||는 왼쪽이 참이면 오른쪽 함수를 호출하지 않는 단락 평가라는 점도 읽으세요.
 */
static void irq_restore_affinity_of_irq(struct irq_desc *desc, unsigned int cpu)
{
	struct irq_data *data = irq_desc_get_irq_data(desc);
	const struct cpumask *affinity = irq_data_get_affinity_mask(data);

	if (!irqd_affinity_is_managed(data) || !desc->action ||
	    !irq_data_get_irq_chip(data) || !cpumask_test_cpu(cpu, affinity))
		return;

	/*
	 * Don't restore suspended interrupts here when a system comes back
	 * from S3. They are reenabled via resume_device_irqs().
	 */
	if (desc->istate & IRQS_SUSPENDED)
		return;

	if (irqd_is_managed_and_shutdown(data))
		irq_startup(desc, IRQ_RESEND, IRQ_START_COND);

	/*
	 * If the interrupt can only be directed to a single target
	 * CPU then it is already assigned to a CPU in the affinity
	 * mask. No point in trying to move it around unless the
	 * isolation mechanism requests to move it to an upcoming
	 * housekeeping CPU.
	 */

/* 학습 해설
 * CPU 온라인 IRQ 순회: 저장소 잠금과 descriptor 잠금의 역할
 * 전체 IRQ 목록을 순회하는 동안 객체가 생성·제거되는 문제와 한 IRQ의 내부 상태가 동시에 바뀌는 문제는 보호 범위가 다릅니다.
 * irq_affinity_online_cpu는 먼저 irq_lock_sparse를 잡아 IRQ descriptor 저장소의 변경 경로와 순회를 직렬화합니다. active IRQ마다 descriptor를 찾고 raw_spin_lock_irq로 해당 객체 잠금과 로컬 IRQ 비활성을 적용한 뒤 복원 함수를 호출합니다. 각 객체에서 raw_spin_unlock_irq를 실행하고 전체 순회가 끝나면 irq_unlock_sparse를 호출합니다. 마지막 반환은 항상 0입니다. 개별 복원 helper가 void이고 하위 오류를 모으지 않으므로 0은 모든 IRQ 재설정의 성공 집계가 아닙니다.
 * 외부 저장소 잠금→첫 IRQ 잠금·복원·해제→다음 IRQ 잠금·복원·해제→외부 해제 순서를 그리세요. kernel/cpu.c에서 이 함수가 CPU hotplug startup 콜백으로 등록되는 연결도 따라가세요.
 */
int irq_affinity_online_cpu(unsigned int cpu)
{
	struct irq_desc *desc;
	unsigned int irq;

	irq_lock_sparse();
	for_each_active_irq(irq) {
		desc = irq_to_desc(irq);
		raw_spin_lock_irq(&desc->lock);
		irq_restore_affinity_of_irq(desc, cpu);
		raw_spin_unlock_irq(&desc->lock);
	}
	irq_unlock_sparse();

	return 0;
}

/* 학습 해설
 * 절전 깨우기 IRQ: 준비 표시를 소비하고 사건을 남기기
 * 절전 진입 중 깨우기 신호가 오면 일반 장치 처리와 별도로 전원 관리 코드에 알리고, 나중에 처리할 사건도 잃지 않도록 상태를 남겨야 합니다.
 * irq_pm_check_wakeup은 IRQD_WAKEUP_ARMED가 있을 때만 동작합니다. 먼저 준비 표시를 지우고 IRQS_SUSPENDED와 IRQS_PENDING을 OR로 세운 뒤 depth를 1 늘립니다. 이어 irq_disable로 IRQ를 비활성화하고 pm_system_irq_wakeup에 IRQ 번호를 전달한 뒤 true입니다. 준비 표시가 없으면 아무 변경 없이 false입니다. 깨우기 가능 설정인 wakeup_set과 이번 절전 구간의 준비 상태인 wakeup_armed는 서로 다른 조건입니다.
 * ARMED=true, depth=0에서 시작해 ARMED=false, SUSPENDED=true, PENDING=true, depth=1 순서를 적으세요. 다시 호출해도 재무장 전에는 false이며 depth를 또 늘리지 않는 이유를 찾으세요.
 */
bool irq_pm_check_wakeup(struct irq_desc *desc)
{
	if (irqd_is_wakeup_armed(&desc->irq_data)) {
		irqd_clear(&desc->irq_data, IRQD_WAKEUP_ARMED);
		desc->istate |= IRQS_SUSPENDED | IRQS_PENDING;
		desc->depth++;
		irq_disable(desc);
		pm_system_irq_wakeup(irq_desc_get_irq(desc));
		return true;
	}
	return false;
}

/*
 * Called from __setup_irq() with desc->lock held after @action has
 * been installed in the action chain.
 */
void irq_pm_install_action(struct irq_desc *desc, struct irqaction *action)
{
	desc->nr_actions++;

	if (action->flags & IRQF_FORCE_RESUME)
		desc->force_resume_depth++;

	WARN_ON_ONCE(desc->force_resume_depth &&
		     desc->force_resume_depth != desc->nr_actions);

/* 학습 해설
 * 공유 IRQ 절전 정책: action 수와 플래그별 수를 따로 세는 이유
 * 여러 장치가 IRQ 하나를 공유하면 한 장치의 절전 정책이 같은 선을 쓰는 다른 장치와 충돌할 수 있어 공유 전체의 정책을 확인해야 합니다.
 * irq_pm_install_action은 action 연결 후 desc->lock을 보유한 상태에서 호출됩니다. nr_actions를 늘리고 FORCE_RESUME이면 force_resume_depth도 늘립니다. 강제 복원을 요청한 action이 하나라도 있는데 전체 action 수와 다르면 WARN_ON_ONCE입니다. NO_SUSPEND이면 no_suspend_depth를 늘리고, 그렇지 않고 COND_SUSPEND이면 cond_suspend_depth를 늘립니다. NO_SUSPEND가 존재할 때 이 두 카운터의 합이 전체 action 수와 다르면 다시 경고합니다. 경고는 설치를 취소하거나 카운터를 되돌리지 않습니다.
 * action 2개 중 하나만 FORCE_RESUME이면 1 != 2여서 경고입니다. NO_SUSPEND 하나와 COND_SUSPEND 하나면 1+1=2라 두 번째 정책 검사에 맞습니다. 둘 중 하나가 아무 관련 플래그도 없으면 합이 부족합니다.
 */
void irq_pm_install_action(struct irq_desc *desc, struct irqaction *action)
{
	desc->nr_actions++;

	if (action->flags & IRQF_FORCE_RESUME)
		desc->force_resume_depth++;

	WARN_ON_ONCE(desc->force_resume_depth &&
		     desc->force_resume_depth != desc->nr_actions);

	if (action->flags & IRQF_NO_SUSPEND)
		desc->no_suspend_depth++;
	else if (action->flags & IRQF_COND_SUSPEND)
		desc->cond_suspend_depth++;

	WARN_ON_ONCE(desc->no_suspend_depth &&
		     (desc->no_suspend_depth +
			desc->cond_suspend_depth) != desc->nr_actions);
}

/*
 * Called from __free_irq() with desc->lock held after @action has
 * been removed from the action chain.
 */
void irq_pm_remove_action(struct irq_desc *desc, struct irqaction *action)
{

/* 학습 해설
 * 공유 IRQ action 제거: 등록 때 센 정책을 대칭으로 돌려놓기
 * 장치 handler를 제거한 뒤에도 절전 정책 카운터가 남으면 이제는 존재하지 않는 장치의 요구 때문에 IRQ 전체의 정책이 달라질 수 있습니다.
 * irq_pm_remove_action은 action 연결 제거 후 desc->lock을 보유한 상태에서 호출됩니다. nr_actions를 줄이고 FORCE_RESUME이면 force_resume_depth를 줄입니다. NO_SUSPEND이면 no_suspend_depth를 줄이고 아니면서 COND_SUSPEND이면 cond_suspend_depth를 줄입니다. 설치와 같은 else if 구조를 써 같은 분류를 되돌립니다. 이 함수는 목록에서 action을 직접 제거하지 않고, 중복 제거를 막는 검사를 하거나 메모리를 해제하지도 않습니다.
 * NO_SUSPEND 1개와 COND_SUSPEND 1개인 상태에서 첫 action을 제거하면 nr_actions=1, no_suspend=0, cond_suspend=1입니다. 등록·제거가 정확히 한 번씩 대응해야 한다는 수명 계약을 적으세요.
 */
void irq_pm_remove_action(struct irq_desc *desc, struct irqaction *action)
{
	desc->nr_actions--;

	if (action->flags & IRQF_FORCE_RESUME)
		desc->force_resume_depth--;

	if (action->flags & IRQF_NO_SUSPEND)
		desc->no_suspend_depth--;
	else if (action->flags & IRQF_COND_SUSPEND)
		desc->cond_suspend_depth--;
}

