 * 일반 IRQ, NO_SUSPEND 공유 IRQ, wakeup 설정 IRQ의 경로를 따로 그리세요. NO_SUSPEND 검사가 wakeup 검사보다 먼저이므로 둘이 겹치면 이 함수에서 ARMED를 세우지 않는 순서도 확인하세요.
 */
static bool suspend_device_irq(struct irq_desc *desc)
{
	unsigned long chipflags = irq_desc_get_chip(desc)->flags;
	struct irq_data *irqd = &desc->irq_data;

	if (!desc->action || irq_desc_is_chained(desc) ||
	    desc->no_suspend_depth)
		return false;

	if (irqd_is_wakeup_set(irqd)) {
		irqd_set(irqd, IRQD_WAKEUP_ARMED);

		if ((chipflags & IRQCHIP_ENABLE_WAKEUP_ON_SUSPEND) &&
		     irqd_irq_disabled(irqd)) {
			/*
			 * Interrupt marked for wakeup is in disabled state.
			 * Enable interrupt here to unmask/enable in irqchip
			 * to be able to resume with such interrupts.
			 */
			__enable_irq(desc);
			irqd_set(irqd, IRQD_IRQ_ENABLED_ON_SUSPEND);
		}
		/*
		 * We return true here to force the caller to issue
		 * synchronize_irq(). We need to make sure that the
		 * IRQD_WAKEUP_ARMED is visible before we return from
		 * suspend_device_irqs().
		 */

/* 학습 해설
 * 일반 IRQ 절전 중단: disable과 chip mask가 별도인 이유
 * 소프트웨어에서 IRQ 처리를 막았다는 사실만으로 모든 하드웨어가 절전 중 불필요한 신호를 차단했다고 보장할 수는 없습니다.
 * 깨우기 IRQ가 아닌 일반 경로는 IRQS_SUSPENDED를 세우고 __disable_irq를 호출합니다. chip의 IRQCHIP_MASK_ON_SUSPEND 플래그가 있으면 mask_irq도 별도로 호출합니다. 원문은 깨우기 소스 구성 기능이 없는 하드웨어에서 비깨우기 IRQ를 chip 수준에서 가려야 하는 요구를 설명합니다. 이 분기도 true로 끝납니다. __disable_irq는 중첩 depth를 올리고 이전 값이 0일 때 하드웨어 disable 경로를 호출하므로 depth 증가와 매번 하드웨어 조작은 같은 뜻이 아닙니다.
 * depth=0과 depth=2인 시작 상태에서 각각 __disable_irq 후 depth=1과 3이 되는 것을 계산하세요. MASK_ON_SUSPEND가 켜진 경우는 그와 별도로 chip mask 호출을 표시하세요.
 */
static bool suspend_device_irq(struct irq_desc *desc)
{
	unsigned long chipflags = irq_desc_get_chip(desc)->flags;
	struct irq_data *irqd = &desc->irq_data;

	if (!desc->action || irq_desc_is_chained(desc) ||
	    desc->no_suspend_depth)
		return false;

	if (irqd_is_wakeup_set(irqd)) {
		irqd_set(irqd, IRQD_WAKEUP_ARMED);

		if ((chipflags & IRQCHIP_ENABLE_WAKEUP_ON_SUSPEND) &&
		     irqd_irq_disabled(irqd)) {
			/*
			 * Interrupt marked for wakeup is in disabled state.
			 * Enable interrupt here to unmask/enable in irqchip
			 * to be able to resume with such interrupts.
			 */
			__enable_irq(desc);
			irqd_set(irqd, IRQD_IRQ_ENABLED_ON_SUSPEND);
		}
		/*
		 * We return true here to force the caller to issue
		 * synchronize_irq(). We need to make sure that the
		 * IRQD_WAKEUP_ARMED is visible before we return from
		 * suspend_device_irqs().
		 */

/* 학습 해설
 * 절전 IRQ 동기화: 잠금을 놓은 뒤 실행 종료를 기다리는 이유
 * IRQ를 끄거나 깨우기 준비 표시를 세운 순간에도 다른 CPU 또는 처리 스레드가 이전 IRQ 처리를 실행 중일 수 있어 그 경계를 맞춰야 합니다.
 * suspend_device_irqs는 전체 descriptor를 순회하되 nested thread IRQ는 건너뜁니다. raw_spin_lock_irqsave로 descriptor 잠금과 로컬 인터럽트 상태를 저장하고 suspend_device_irq를 호출합니다. raw_spin_unlock_irqrestore로 잠금을 풀고 로컬 상태를 복원한 다음, helper 결과가 true이면 synchronize_irq로 해당 처리와 동기화합니다. wakeup 준비의 경우에도 동기화가 필요하므로 true입니다. 이 함수는 모든 IRQ를 잠금 하나로 감싸거나 잠금을 보유한 채 synchronize_irq를 기다리지 않습니다.
 * 잠금 획득→상태 변경→잠금 해제→실행 동기화 순서로 네 칸을 그리세요. helper에서 NO_SUSPEND로 생략된 IRQ에는 이 함수가 synchronize_irq도 호출하지 않는 것을 따라가세요.
 */
void suspend_device_irqs(void)
{
	struct irq_desc *desc;
	int irq;

	for_each_irq_desc(irq, desc) {
		unsigned long flags;
		bool sync;

		if (irq_settings_is_nested_thread(desc))
			continue;
		raw_spin_lock_irqsave(&desc->lock, flags);
		sync = suspend_device_irq(desc);
		raw_spin_unlock_irqrestore(&desc->lock, flags);

		if (sync)
			synchronize_irq(irq);
	}
}

static void resume_irq(struct irq_desc *desc)
{
	struct irq_data *irqd = &desc->irq_data;

	irqd_clear(irqd, IRQD_WAKEUP_ARMED);

/* 학습 해설
 * 절전 중 임시 enable 복원: 원래 꺼져 있던 IRQ는 꺼진 상태로
 * 시스템을 깨우려고 잠깐 enable한 IRQ를 복귀 후에도 그대로 켜 두면 절전 전 드라이버가 의도했던 비활성 상태가 깨집니다.
 * resume_irq는 먼저 IRQD_WAKEUP_ARMED를 지웁니다. IRQD_IRQ_ENABLED_ON_SUSPEND가 있으면 __disable_irq로 절전 진입 때의 enable 수준을 되돌리고 그 표시를 지웁니다. 그 다음 IRQS_SUSPENDED가 있으면 공통 resume 경로로 이동합니다. 이 순서 덕분에 임시 enable 복구와 깨우기 사건으로 생긴 suspend 복구가 각각 대응합니다. depth가 여러 수준이면 enable이 하드웨어를 켜지 않고 카운터만 낮출 수도 있어 원래 상태를 기준으로 읽어야 합니다.
 * 일반적인 depth=1 비활성 IRQ를 절전용으로 enable해 0이 되고, 깨우기 사건이 와서 1이 된 사례를 그리세요. 복귀 때 임시 enable을 되돌려 2, suspend 수준을 enable로 풀어 1이 되어 원래 비활성 수준으로 돌아옵니다. 정상 하위 호출을 가정한 상태 계산입니다.
 */
static void resume_irq(struct irq_desc *desc)
{
	struct irq_data *irqd = &desc->irq_data;

	irqd_clear(irqd, IRQD_WAKEUP_ARMED);

	if (irqd_is_enabled_on_suspend(irqd)) {
		/*
		 * Interrupt marked for wakeup was enabled during suspend
		 * entry. Disable such interrupts to restore them back to
		 * original state.
		 */
		__disable_irq(desc);
		irqd_clear(irqd, IRQD_IRQ_ENABLED_ON_SUSPEND);
	}

	if (desc->istate & IRQS_SUSPENDED)
		goto resume;

	/* Force resume the interrupt? */
	if (!desc->force_resume_depth)
		return;

	/* Pretend that it got disabled ! */
	desc->depth++;
	irq_state_set_disabled(desc);

/* 학습 해설
 * 강제 IRQ 복원: 중단 표시가 없어도 enable 경로를 거치는 이유
 * 일부 장치나 컨트롤러는 절전 때 일반 중단 경로를 거치지 않았어도 복귀 시 enable 처리를 다시 수행해야 하므로 별도 정책을 둡니다.
 * IRQS_SUSPENDED가 없고 force_resume_depth도 0이면 resume_irq는 반환합니다. 중단 표시는 없지만 강제 복원 정책이 있으면 depth를 1 늘리고 irq_state_set_disabled와 irq_state_set_masked로 소프트웨어 상태를 만든 뒤 공통 resume 경로로 갑니다. 공통 경로는 IRQS_SUSPENDED를 지우고 __enable_irq를 호출합니다. 상태 표시를 세우는 helper 자체를 하드웨어 mask 콜백 실행으로 해석하면 안 됩니다. depth 균형을 만들고 정상 enable 경로에 연결하는 구조입니다.
 * SUSPENDED=false·force=0, false·force>0, true의 세 경로를 그리세요. force 경로에서는 depth++가 있고 기존 suspend 경로에서는 여기서 depth를 추가하지 않는 차이를 적으세요.
 */
static void resume_irq(struct irq_desc *desc)
{
	struct irq_data *irqd = &desc->irq_data;

	irqd_clear(irqd, IRQD_WAKEUP_ARMED);

	if (irqd_is_enabled_on_suspend(irqd)) {
		/*
		 * Interrupt marked for wakeup was enabled during suspend
		 * entry. Disable such interrupts to restore them back to
		 * original state.
		 */
		__disable_irq(desc);
		irqd_clear(irqd, IRQD_IRQ_ENABLED_ON_SUSPEND);
	}

	if (desc->istate & IRQS_SUSPENDED)
		goto resume;

	/* Force resume the interrupt? */
	if (!desc->force_resume_depth)
		return;

	/* Pretend that it got disabled ! */
	desc->depth++;
	irq_state_set_disabled(desc);

/* 학습 해설
 * 조기 IRQ 복원 필터: 일반 복원에서도 조기 IRQ가 다시 방문된다
 * 주석의 요약만 보고 조기 복원과 일반 복원이 완전히 분리된 집합이라고 생각하면 실제 반복 호출과 강제 복원 동작을 놓칩니다.
 * resume_irqs는 첫 action이 있고 IRQF_EARLY_RESUME가 있으면 is_early로 봅니다. !is_early && want_early일 때만 건너뜁니다. 따라서 want_early=true는 조기 IRQ만 선택하지만 false는 조기 IRQ도 제외하지 않습니다. nested thread IRQ는 두 경우 모두 생략합니다. 선택된 IRQ는 irqsave 잠금 안에서 resume_irq를 호출합니다. 조기에 이미 정상 복원되고 강제 복원 정책이 없다면 두 번째 방문은 보통 상태 정리 후 반환하지만 FORCE_RESUME가 있으면 다시 강제 경로를 밟을 수 있습니다.
 * is_early=false/true와 want_early=false/true의 2×2 표를 만들고 생략되는 칸은 false·true 하나임을 확인하세요. IRQF_EARLY_RESUME는 이 코드에서 action 목록 전체를 순회해 OR한 값이 아니라 첫 action의 플래그입니다.
 */
static void resume_irqs(bool want_early)
{
	struct irq_desc *desc;
	int irq;

	for_each_irq_desc(irq, desc) {
		unsigned long flags;
		bool is_early = desc->action &&
			desc->action->flags & IRQF_EARLY_RESUME;

		if (!is_early && want_early)
			continue;
		if (irq_settings_is_nested_thread(desc))
			continue;

		raw_spin_lock_irqsave(&desc->lock, flags);
		resume_irq(desc);
		raw_spin_unlock_irqrestore(&desc->lock, flags);
	}
}

/**
 * rearm_wake_irq - rearm a wakeup interrupt line after signaling wakeup
 * @irq: Interrupt to rearm
 */
void rearm_wake_irq(unsigned int irq)

/* 학습 해설
 * 깨우기 재무장: 이미 알린 IRQ를 다시 받을 준비
 * 깨우기 사건을 한 번 알렸다고 이후 신호를 항상 버려도 되는 것은 아니므로 상태 조건을 확인해 같은 IRQ를 다시 준비하는 API가 있습니다.
 * rearm_wake_irq는 IRQ_GET_DESC_CHECK_GLOBAL 조건으로 descriptor와 buslock을 얻습니다. 얻지 못하면 조용히 반환합니다. IRQS_SUSPENDED가 없거나 wakeup 설정이 아니면 공통 unlock으로 갑니다. 둘 다 맞으면 SUSPENDED를 지우고 WAKEUP_ARMED를 세운 뒤 __enable_irq를 호출합니다. descriptor를 얻은 모든 경로는 irq_put_desc_busunlock으로 종료합니다. 이 함수는 void이며 wakeup 설정 자체를 새로 만들지 않고, 여기서 PENDING 비트를 직접 지우지도 않습니다.
 * SUSPENDED=true와 wakeup_set=true를 두 입력 칸에 놓고 네 조합 중 하나만 재무장하는 것을 확인하세요. 상태를 먼저 바꾼 뒤 enable하는 순서와 조건 실패에서도 잠금을 푸는 경로를 표시하세요.
 */
void rearm_wake_irq(unsigned int irq)
{
	unsigned long flags;
	struct irq_desc *desc = irq_get_desc_buslock(irq, &flags, IRQ_GET_DESC_CHECK_GLOBAL);

	if (!desc)
		return;

	if (!(desc->istate & IRQS_SUSPENDED) ||
	    !irqd_is_wakeup_set(&desc->irq_data))
		goto unlock;

	desc->istate &= ~IRQS_SUSPENDED;
	irqd_set(&desc->irq_data, IRQD_WAKEUP_ARMED);
	__enable_irq(desc);

unlock:
	irq_put_desc_busunlock(desc, flags);
}

/**
 * irq_pm_syscore_resume - enable interrupt lines early
 *
 * Enable all interrupt lines with %IRQF_EARLY_RESUME set.
 */
static void irq_pm_syscore_resume(void)

/* 학습 해설
 * IRQ 조기 복원 등록: 함수 포인터와 부팅 초기화 연결
 * 함수를 정의하기만 해서는 시스템 복귀 때 자동 실행되지 않으므로 전원 관리 프레임워크에 호출 대상을 등록하는 연결이 필요합니다.
 * irq_pm_syscore_ops라는 정적 struct syscore_ops는 .resume 멤버에 irq_pm_syscore_resume 함수 포인터를 넣습니다. 이 wrapper는 resume_irqs(true)를 호출합니다. __init 함수 irq_pm_init_ops는 register_syscore_ops로 표를 등록하고 0을 반환하며 device_initcall이 부팅 초기화 경로와 연결합니다. 이 파일의 표에는 suspend 콜백을 지정하지 않습니다. 지정하지 않은 정적 멤버가 다른 숨은 함수로 자동 연결된다고 가정하면 안 됩니다.
 * device_initcall→irq_pm_init_ops→register_syscore_ops→복귀 때 .resume 호출→resume_irqs(true)의 화살표를 그리세요. 등록 시점과 실제 복귀 콜백 실행 시점이 다름을 적으세요.
 */
static int __init irq_pm_init_ops(void)
{
	register_syscore_ops(&irq_pm_syscore_ops);
	return 0;
}

device_initcall(irq_pm_init_ops);

/**
 * resume_device_irqs - enable interrupt lines disabled by suspend_device_irqs()
 *
 * Enable all non-%IRQF_EARLY_RESUME interrupt lines previously
 * disabled by suspend_device_irqs() that have the IRQS_SUSPENDED flag
 * set as well as those with %IRQF_FORCE_RESUME.
 */
void resume_device_irqs(void)
{
	resume_irqs(false);
}

/* 학습 해설
 * 일반 IRQ 복귀 진입점: wrapper와 실제 정책을 나눠 읽기
 * 짧은 공개 함수도 실제 동작은 내부 helper가 결정하므로 함수 이름이나 문서 한 문장만으로 처리 대상을 단정하면 안 됩니다.
 * resume_device_irqs의 본문은 resume_irqs(false) 호출 하나입니다. 조기 복원 wrapper는 true를 전달하므로 두 진입점의 차이는 내부 필터 인자에 있습니다. 실제 복원 여부는 각 descriptor의 SUSPENDED, FORCE_RESUME, ENABLED_ON_SUSPEND 상태와 nested 여부에 따라 달라집니다. 이 함수도 void이며 각 하드웨어 복원 결과를 수집해 오류 코드를 반환하는 인터페이스가 아닙니다. suspend_device_irqs와 대응해 호출하되 개별 상태 전이를 함께 따라야 합니다.
 * 일반 절전 IRQ는 suspend에서 SUSPENDED를 세우고 disable한 뒤 resume에서 표시를 지우고 enable하는 흐름을 만드세요. NO_SUSPEND와 FORCE_RESUME가 있는 경우는 같은 그림에 억지로 넣지 말고 별도 가지로 그리세요.
 */
void resume_device_irqs(void)
{
	resume_irqs(false);
}

/* 학습 해설
 * IRQ 폴링 완료 대기: 같은 CPU의 작업을 기다리면 멈추는 이유
 * 정상 인터럽트 처리와 복구용 폴링이 겹치면 폴링 종료를 기다려야 하지만 기다리는 위치에 따라 상대가 더는 진행하지 못할 수 있습니다.
 * irq_wait_for_poll은 desc->lock을 보유하고 들어오는 함수입니다. irq_poll_cpu가 현재 CPU와 같으면 WARN_ONCE를 내고 false로 반환합니다. CONFIG_SMP에서는 잠금을 놓고 IRQ_INPROGRESS가 사라질 때까지 cpu_relax로 바쁜 대기를 한 뒤 잠금을 다시 잡습니다. 잠금 재획득 사이에 처리가 다시 시작될 수 있어 do-while로 상태를 재검사합니다. 끝에서 disabled가 아니고 action도 남아 있어야 true입니다. SMP가 아닌 빌드의 대체 경로는 false이며 잠금을 풀지 않습니다.
 * CPU 0의 폴링을 CPU 1이 기다리는 경우와 CPU 0이 자기 폴링을 기다리는 경우를 나눠 그리세요. 반환하는 모든 경로에서 호출자가 보유한 descriptor 잠금이 유지되는지도 확인하세요.
 */
bool irq_wait_for_poll(struct irq_desc *desc)
	__must_hold(&desc->lock)
{
	if (WARN_ONCE(irq_poll_cpu == smp_processor_id(),
		      "irq poll in progress on cpu %d for irq %d\n",
		      smp_processor_id(), desc->irq_data.irq))
		return false;

#ifdef CONFIG_SMP
	do {
		raw_spin_unlock(&desc->lock);
		while (irqd_irq_inprogress(&desc->irq_data))
			cpu_relax();
		raw_spin_lock(&desc->lock);
	} while (irqd_irq_inprogress(&desc->irq_data));
	/* Might have been disabled in meantime */
	return !irqd_irq_disabled(&desc->irq_data) && desc->action;
#else
	return false;
#endif
}


/*
 * Recovery handler for misrouted interrupts.
 */

/* 학습 해설
 * 복구용 IRQ 시도: force도 모든 제한을 없애지는 않는다
 * 알 수 없는 인터럽트의 주인을 찾겠다고 모든 handler를 무조건 호출하면 CPU 전용 처리나 중첩 스레드의 실행 계약을 깨뜨릴 수 있습니다.
 * try_one_irq는 descriptor 잠금을 잡고 per-CPU, nested thread, 명시적 polled IRQ를 제외합니다. disabled 상태이면 force가 참일 때만 다음으로 진행합니다. action이 없거나 첫 action에 IRQF_SHARED가 없거나 __IRQF_TIMER가 있으면 제외합니다. 공유 플래그는 모든 handler가 동의해야 한다는 등록 계약 때문에 첫 action만 확인합니다. force=true가 무시하는 것은 disabled 거절 조건이며 나머지 종류·공유·타이머 검사를 없애지 않습니다.
 * force=true인 비활성 공유 IRQ와 force=true인 CPU 전용 IRQ를 비교하세요. 전자는 이후 조건을 검사하지만 후자는 첫 분기에서 제외됩니다. 모든 조기 종료는 공통 out에서 잠금을 풉니다.
 */
static int try_one_irq(struct irq_desc *desc, bool force)
{
	irqreturn_t ret = IRQ_NONE;
	struct irqaction *action;

	raw_spin_lock(&desc->lock);

	/*
	 * PER_CPU, nested thread interrupts and interrupts explicitly
	 * marked polled are excluded from polling.
	 */
	if (irq_settings_is_per_cpu(desc) ||
	    irq_settings_is_nested_thread(desc) ||
	    irq_settings_is_polled(desc))
		goto out;

	/*
	 * Do not poll disabled interrupts unless the spurious
	 * disabled poller asks explicitly.
	 */
	if (irqd_irq_disabled(&desc->irq_data) && !force)
		goto out;

	/*
	 * All handlers must agree on IRQF_SHARED, so we test just the
	 * first.
	 */

/* 학습 해설
 * IRQ 복구 중복 실행: 다른 CPU가 처리 중이면 PENDING만 남기기
 * 이미 다른 CPU가 같은 IRQ를 처리 중인데 복구 코드가 다시 실행하면 동일 장치 상태를 두 실행 흐름이 동시에 처리할 수 있습니다.
 * 후보 조건을 통과했지만 IRQ_INPROGRESS가 켜져 있으면 IRQS_PENDING을 세우고 공통 종료로 갑니다. 직접 handler를 중복 실행하지 않습니다. 진행 중이 아니면 IRQS_POLL_INPROGRESS를 세우고 handle_irq_event를 호출합니다. 반환이 정확히 IRQ_HANDLED일 때 ret를 성공으로 기억합니다. 합성값 3은 이 == 비교에서는 값 1과 같지 않습니다. 이어 PENDING이 남고 action도 있으면 반복합니다. action은 각 호출 뒤 다시 읽습니다. 마지막에 POLL_INPROGRESS를 지우고 잠금을 풀며 결과는 ret == IRQ_HANDLED입니다.
 * 첫 호출에서는 HANDLED, 다음 호출에서는 NONE이 나와도 ret가 성공으로 남는 경로를 따라가세요. 반대로 PENDING을 남겼다는 사실만으로 이 함수가 성공 1을 반환하지는 않음을 확인하세요.
 */
static int try_one_irq(struct irq_desc *desc, bool force)
{
	irqreturn_t ret = IRQ_NONE;
	struct irqaction *action;

	raw_spin_lock(&desc->lock);

	/*
	 * PER_CPU, nested thread interrupts and interrupts explicitly
	 * marked polled are excluded from polling.
	 */
	if (irq_settings_is_per_cpu(desc) ||
	    irq_settings_is_nested_thread(desc) ||
	    irq_settings_is_polled(desc))
		goto out;

	/*
	 * Do not poll disabled interrupts unless the spurious
	 * disabled poller asks explicitly.
	 */
	if (irqd_irq_disabled(&desc->irq_data) && !force)
		goto out;

	/*
	 * All handlers must agree on IRQF_SHARED, so we test just the
	 * first.
	 */

/* 학습 해설
 * 잘못 전달된 IRQ 찾기: 원자 카운터로 폴러 한 개만 진입시키기
 * IRQ를 잘못 전달받았을 때 다른 선의 handler를 시험하는 복구를 여러 CPU가 동시에 수행하면 중복 작업과 상태 경쟁이 커집니다.
 * misrouted_irq는 atomic_inc_return으로 irq_poll_active를 증가시켜 결과가 1일 때만 순회합니다. 처음 0이었던 카운터를 1로 바꾼 호출이 폴러가 되고, 다른 호출은 종료 경로로 갑니다. 실제 폴러는 현재 CPU를 irq_poll_cpu에 기록하고 IRQ 0 및 이미 시험한 입력 irq를 제외해 try_one_irq(desc,false)를 호출합니다. 한 곳이라도 성공하면 ok=1이지만 순회를 즉시 중단하지는 않습니다. 모든 진입은 out에서 카운터를 감소시킵니다.
 * CPU A가 0→1, CPU B가 1→2 후 생략하고 2→1, A 종료 때 1→0인 순서를 적으세요. 성공한 IRQ 개수 대신 하나라도 처리됐는지 나타내는 0/1이 반환됩니다.
 */
static int misrouted_irq(int irq)
{
	struct irq_desc *desc;
	int i, ok = 0;

	if (atomic_inc_return(&irq_poll_active) != 1)
		goto out;

	irq_poll_cpu = smp_processor_id();

	for_each_irq_desc(i, desc) {
		if (!i)
			 continue;

		if (i == irq)	/* Already tried */
			continue;

		if (try_one_irq(desc, false))
			ok = 1;
	}
out:
	atomic_dec(&irq_poll_active);
	/* So the caller can adjust the irq error counts */
	return ok;
}

/* 학습 해설
 * 중단된 IRQ 주기 점검: 타이머 재예약과 제한된 강제 실행
 * 반복 이상으로 IRQ를 껐더라도 장치 상태가 달라졌을 수 있어 제한된 복구 시도를 주기적으로 수행하는 경로가 필요합니다.
 * 정적 poll_spurious_irq_timer는 poll_spurious_irqs를 콜백으로 사용합니다. 이 함수도 irq_poll_active로 폴러를 직렬화하고 IRQ 0을 제외합니다. desc->istate를 지역 state로 읽고 compiler barrier 뒤 SPURIOUS_DISABLED가 있는 항목만 고릅니다. 해당 IRQ에서는 로컬 인터럽트를 끄고 try_one_irq(desc,true)를 호출한 뒤 다시 켭니다. 마지막에는 진입에 실패한 경우까지 카운터를 감소시키고 jiffies+HZ/10으로 타이머를 재예약합니다. 처리 성공만으로 이 함수가 SPURIOUS_DISABLED를 지우거나 정상 IRQ enable을 수행하지는 않습니다.
 * HZ=1000이면 간격 식은 100 tick이고 HZ=250이면 정수 나눗셈으로 25 tick입니다. 약 0.1초를 목표로 한 예약 시점이지 콜백 실행이 정확히 그 순간이라고 보장하는 값은 아닙니다.
 */
static void poll_spurious_irqs(struct timer_list *unused)
{
	struct irq_desc *desc;
	int i;

	if (atomic_inc_return(&irq_poll_active) != 1)
		goto out;
	irq_poll_cpu = smp_processor_id();

	for_each_irq_desc(i, desc) {
		unsigned int state;

		if (!i)
			 continue;

		/* Racy but it doesn't matter */
		state = desc->istate;
		barrier();
		if (!(state & IRQS_SPURIOUS_DISABLED))
			continue;

		local_irq_disable();
		try_one_irq(desc, true);
		local_irq_enable();
	}
out:

/* 학습 해설
 * IRQ 결과 검증: 합성 결과 3과 잘못된 반환값 구별
 * 공유 IRQ에서는 여러 handler의 결과 비트를 합치므로 단일 handler의 반환값 검사와 합성 결과 검사의 규칙을 구별해야 합니다.
 * bad_action_ret는 입력을 unsigned int r로 받아 IRQ_HANDLED|IRQ_WAKE_THREAD보다 큰지 검사합니다. 이 기준은 1|2=3이므로 0,1,2,3은 이 검사에서 정상 범위입니다. 그 밖의 값은 1을 반환해 잘못됐다고 알립니다. 값 3은 처리 완료와 스레드 요청이 합쳐진 결과로 유효할 수 있습니다. 그러나 handle.c의 개별 callback 결과 switch와 이 합성 결과 검사는 다른 위치이므로 단일 handler가 마음대로 3을 반환해도 모든 경로에서 적절하다는 뜻은 아닙니다.
 * 0,1,2,3,4를 넣어 결과 0,0,0,0,1을 계산하세요. likely는 흔한 분기에 대한 힌트이며 비교 결과를 강제로 참으로 만들거나 범위를 변경하지 않습니다.
 */
static inline int bad_action_ret(irqreturn_t action_ret)
{
	unsigned int r = action_ret;

	if (likely(r <= (IRQ_HANDLED | IRQ_WAKE_THREAD)))
		return 0;
	return 1;
}

/*
 * If 99,900 of the previous 100,000 interrupts have not been handled
 * then assume that the IRQ is stuck in some manner. Drop a diagnostic
 * and try to turn the IRQ off.
 *
 * (The other 100-of-100,000 interrupts may have been a correctly
 *  functioning device sharing an IRQ with the failing one)
 */
static void __report_bad_irq(struct irq_desc *desc, irqreturn_t action_ret)
{
	unsigned int irq = irq_desc_get_irq(desc);
	struct irqaction *action;
	unsigned long flags;

	if (bad_action_ret(action_ret)) {
		printk(KERN_ERR "irq event %d: bogus return value %x\n",
				irq, action_ret);

/* 학습 해설
 * 이상 IRQ 보고: handler 목록 수명과 출력 횟수 제한
 * 문제 원인을 찾으려면 등록된 handler를 출력해야 하지만 보고 중 다른 경로가 handler를 제거할 수 있어 단순 포인터 순회는 안전하지 않습니다.
 * __report_bad_irq는 잘못된 반환값이면 bogus return value를, 정상 범위 결과이면 nobody cared 메시지를 출력하고 dump_stack을 호출합니다. handler 목록을 출력할 때는 desc->lock을 irqsave로 잡고 각 handler와 존재하는 thread_fn 주소·심볼을 출력한 뒤 풉니다. note_interrupt 진입에서 처리 중 상태가 설정돼 있어도 descriptor 잠금은 보유하지 않으므로 여기서 별도로 얻습니다. report_bad_irq wrapper는 static count=100을 두고 양수일 때 감소 후 상세 보고합니다. 정지 판정 경로는 wrapper를 거치지 않고 상세 보고를 직접 부릅니다.
 * 잘못된 값 보고 경로와 반복 미처리로 IRQ를 끄는 경로를 나누어 어떤 함수가 호출되는지 표시하세요. static count는 함수 호출마다 100으로 다시 초기화되는 지역 자동 변수가 아닙니다.
 */
static void __report_bad_irq(struct irq_desc *desc, irqreturn_t action_ret)
{
	unsigned int irq = irq_desc_get_irq(desc);
	struct irqaction *action;
	unsigned long flags;

	if (bad_action_ret(action_ret)) {
		printk(KERN_ERR "irq event %d: bogus return value %x\n",
				irq, action_ret);
	} else {
		printk(KERN_ERR "irq %d: nobody cared (try booting with "
				"the \"irqpoll\" option)\n", irq);
	}
	dump_stack();
	printk(KERN_ERR "handlers:\n");

	/*
	 * We need to take desc->lock here. note_interrupt() is called
	 * w/o desc->lock held, but IRQ_PROGRESS set. We might race
	 * with something else removing an action. It's ok to take
	 * desc->lock here. See synchronize_irq().
